-- The templates: an upsert on slug, so a re-run keeps every id.
insert into public.challenge_templates
  (slug, title, description, category, total_days, tags, min_level, published_at)
values
  ('cheering-other-people-on', 'Cheering Other People On', 'For anyone who wants to be the friend, coworker and neighbor who notices good news and celebrates it. Each day is one small way to cheer someone on, even when their success stings a little.', 'Kindness', 365, array['Relationships', 'Communication', 'Values']::text[], 1, '2026-10-26T17:00:00+00:00'::timestamptz),
  ('bouncing-back-from-mistakes', 'Bouncing Back from Mistakes', 'For anyone who replays every slip for days afterward. Each day is one small way to meet a mistake calmly, put right what you can, learn from it and let the rest go.', 'Self-Compassion', 365, array['Self-Compassion', 'Resilience', 'Perfectionism']::text[], 1, '2026-10-26T17:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  total_days   = excluded.total_days,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;

-- The bank of to-dos for each of those templates, replaced wholesale.
delete from public.challenge_days d
  using public.challenge_templates t
  where d.template_id = t.id and t.slug in ('cheering-other-people-on', 'bouncing-back-from-mistakes');

